disponibilidad_por_trimestre = panel_tratado.notna().mean(axis=1)  # fraccion de candidatas con dato en cada trimestre

for nombre, (desde, hasta) in OPCIONES_VENTANA.items():

    en_ventana_opcion, cobertura_opcion, entran_opcion = aplicar_ventana(panel_tratado, nombre, ESCENARIO_BASE["umbral_cobertura"])

    crudo_opcion = panel_ancho[candidatas_base].loc[desde:hasta]

    filas.append(
        {
            "ventana": nombre,
            "trimestres": len(en_ventana_opcion),
            "series_que_entran": len(entran_opcion),
            "casillas_sin_dato": int(en_ventana_opcion.isna().sum().sum()),
            "pct_casillas_con_dato": float(en_ventana_opcion.notna().mean().mean()),
            "ceros_escritos_en_la_ventana": int(vacios_nuevos(crudo_opcion, panel_tratado.loc[desde:hasta]).sum().sum()),
            "disponibilidad_minima": float(disponibilidad_por_trimestre.loc[desde:hasta].min()),
            "trimestres_con_menos_de_90pct": int((disponibilidad_por_trimestre.loc[desde:hasta] < 0.90).sum()),
        }
    )

tabla_ventana_opciones = pd.DataFrame(filas).set_index("ventana")

print("\nTabla 1.5.a. Efecto de cada ventana (con la correccion adoptada en 1.3 y cobertura minima de 0,70)")
print(tabla_ventana_opciones.round(3).to_string())

# COMO LEER LA TABLA 1.5.a
