sombrear(ax1, trimestres_grafico, TRIMESTRES_IPC_INCOMPLETOS, etiqueta="IPC con un mes sin publicar")

eje_trimestres(ax1, trimestres_grafico)

ax1.set_title(f"Deflactor del IPC de EE. UU. (base {ANIO_BASE_PRECIOS} = 1): inflacion acumulada {inflacion_acumulada:.0%}", fontsize=9)

ax1.legend(fontsize=7)

promedios_z = {nombre: estandarizar_columnas(paneles_precios[nombre][monetarias_precios]).mean(axis=1) for nombre in ("A. corrientes", "B. constantes (IPC EE. UU., base 2015)")}

for (nombre, promedio_z), color in zip(promedios_z.items(), (ROJO, AZUL)):

    ax2.plot(range(len(trimestres_grafico)), promedio_z.values, color=color, label=nombre)

