ax1.set_ylabel("promedio del puntaje z de las series en dolares")

ax1.set_title("Promedio del puntaje z de las series en dolares, sin y con el ajuste", fontsize=9)

ax1.legend(fontsize=7)

orden_dif = tabla_habitante_series["dif_max_z"].sort_values()

ax2.barh(orden_dif.index, orden_dif.values, color=[ROJO if tabla_habitante_series.loc[v, "cambia_el_signo"] else AZUL for v in orden_dif.index])

ax2.set_xlabel("diferencia maxima del puntaje z (desvios): sin ajuste contra por habitante")

