# tabla 4: estabilidad ante datos nuevos. Exponentes estimados con datos hasta cada corte
ventanas_estabilidad = CORTES_VENTANA_DISTRIBUCION + [trimestres_grafico[-1]]


def exponentes_por_corte(metodo):
    """Exponente estimado de cada serie transformada con el metodo, con los datos desde el inicio hasta cada corte."""

    filas = {}

    for variable in series_transformadas_por_opcion[metodo]:

        fila = {}

        for corte in ventanas_estabilidad:

            g = serie_en_grano_propio(variable, panel_habitante.loc[:corte])

            try:

                fila[corte] = estimar_exponente(g, metodo) if g.nunique() >= 3 and (metodo != "box_cox" or (g > 0).all()) else np.nan

            except (ValueError, FloatingPointError):

                fila[corte] = np.nan

        filas[variable] = fila

    return pd.DataFrame(filas).T


exponentes_box_cox = exponentes_por_corte("box_cox")

exponentes_yeo_johnson = exponentes_por_corte("yeo_johnson")


def resumen_exponentes(exponentes):
    """Rango del exponente entre cortes y si cambia de sentido (de acentuar los valores altos, exponente mayor que 1, a comprimirlos)."""

    resumen = pd.DataFrame({"rango": exponentes.max(axis=1) - exponentes.min(axis=1)})

    resumen["cambia_de_sentido"] = (exponentes.min(axis=1) < 1) & (exponentes.max(axis=1) > 1)

    return resumen


resumen_box_cox, resumen_yeo_johnson = resumen_exponentes(exponentes_box_cox), resumen_exponentes(exponentes_yeo_johnson)

print(f"\nTabla 4.3.d. Exponente de Box-Cox estimado con los datos desde {trimestres_grafico[0]} hasta cada corte (las {len(exponentes_box_cox)} series que admite)")
