# tabla 6: revision de lo ya transformado al agregar datos, por opcion
def revision_por_corte(opcion):
    """Maxima diferencia, por serie y corte, entre el puntaje z de la serie transformada con los datos hasta el corte y el de la misma serie transformada con todos los datos."""

    completa = paneles_distribucion[opcion]

    revisiones = {}

    for corte in CORTES_VENTANA_DISTRIBUCION:

        parcial, _ = transformar_distribucion(panel_habitante.loc[:corte], opcion)

        revisiones[corte] = (estandarizar_columnas(parcial) - estandarizar_columnas(completa.loc[:corte])).abs().max()

    return pd.DataFrame(revisiones)


revisiones = {opcion: revision_por_corte(opcion) for opcion in OPCIONES_DISTRIBUCION}

tabla_distribucion_revision = pd.DataFrame(
    {
        "series_que_se_revisan": {o: int((r.max(axis=1) > TOLERANCIA_REVISION_Z).sum()) for o, r in revisiones.items()},
        "revision_maxima_z": {o: float(r.max().max()) for o, r in revisiones.items()},
        "revision_mediana_de_las_revisadas": {o: float(r.max(axis=1)[r.max(axis=1) > TOLERANCIA_REVISION_Z].median()) if (r.max(axis=1) > TOLERANCIA_REVISION_Z).any() else 0.0 for o, r in revisiones.items()},
    }
)

print(f"\nTabla 4.3.f. Revision de lo ya transformado al agregar datos (ediciones simuladas con corte en {', '.join(CORTES_VENTANA_DISTRIBUCION)})")
