# tabla 3: el IPC de 2025-Q4
variacion_deflactor = deflactor_t.loc[:trimestres_grafico[-1]].pct_change()

variacion_tipica = float(variacion_deflactor.iloc[-9:-1].mean())

variacion_provisional = float(variacion_deflactor.iloc[-1])

factor_si_fuera_tipico = (1 + variacion_tipica) / (1 + variacion_provisional)


def efecto_deflactor_en_z(factor):
    """Cambio, en desvios de cada serie en dolares, del valor del ultimo trimestre si el deflactor fuera `factor` veces el calculado (aproximado en las series anuales)."""

    efectos = {}

    for variable in monetarias_precios:

        k = 1 + (factor - 1) / 4 if catalogo.loc[variable, "grano_temporal"] == "anio repetido" else factor

        cambio = np.log(1 / k) if variable in series_con_log_base else panel_conteos.loc[trimestres_grafico[-1], variable] * (1 / k - 1)

        efectos[variable] = abs(cambio) / panel_conteos[variable].std()

    return pd.Series(efectos)


efectos_ipc = efecto_deflactor_en_z(factor_si_fuera_tipico)

tabla_ipc = pd.DataFrame(
    {
        f"variacion_del_deflactor_{trimestres_grafico[-1]}": [variacion_provisional],
        "variacion_media_de_los_8_anteriores": [variacion_tipica],
        "factor_si_subiera_lo_tipico": [factor_si_fuera_tipico],
        "cambio_maximo_en_z_de_una_serie": [float(efectos_ipc.max())],
        "cambio_mediano_en_z": [float(efectos_ipc.median())],
    },
    index=["IPC de EE. UU."],
)

print(f"\nTabla 4.6.c. El deflactor de {trimestres_grafico[-1]} (IPC de EE. UU. con un mes sin publicar)")
