        valores_ = [t_.loc[sin_atipicos(p) if excluye else p, columna] if (sin_atipicos(p) if excluye else p) in t_.index else np.nan for p in CANDIDATOS_REFERENCIA]

        colores_ = [AZUL if (sin_atipicos(p) if excluye else p) == PERIODO_REFERENCIA_ELEGIDO else (OCRE if excluye else GRIS) for p in CANDIDATOS_REFERENCIA]

        ax_.bar(posiciones_p + desplazamiento, valores_, width=0.4, color=colores_, label=rotulo)

