#=============================================================================.#
# 7. PONDERACION -----
#=============================================================================.#

# Un esquema de pesos tiene dos partes: el peso de cada serie dentro de su dimension (7.1) y el
# peso de cada dimension en el indice (7.2). Un peso es la importancia relativa con que cuenta una
# columna cuando se combinan todas en un solo numero: una serie con peso doble mueve el indice el
# doble. Esta etapa NO modifica el panel normalizado: solo decide con que importancia se combinan
# sus columnas en la Etapa 8 (el cierre, 7.3, muestra el panel intacto y la tabla de pesos).


## 7.0. Funciones comunes de la ponderacion y la agregacion --------------------------

# Estas funciones son el motor de las Etapas 7 y 8: reciben el panel normalizado y un escenario (un
# diccionario con las mismas claves de ESCENARIO_BASE) y devuelven el indice con sus subindices. Se
# definen aqui, antes de cualquier tabla, porque para comparar los esquemas de pesos (7.1 y 7.2)
# hay que construir el indice con cada uno. Cada opcion que ejecutan se explica y se evalua en su
# subseccion:
#   - pesos de las series dentro de la dimension      funciones de 7.1 (pesos_de_series)
#   - pesos de las dimensiones                        pesos_de_dimensiones (abajo), evaluada en 7.2
#   - forma de agregar                                combinar (abajo), evaluada en 8.1
#   - orden de la agregacion y trimestres sin dato    agregar_indice (abajo), evaluada en 8.2

def pesos_de_dimensiones(subindices, series_por_dimension, opcion):
    """Pesos de las dimensiones (columnas de subindices) segun la opcion elegida."""

    dimensiones = list(subindices.columns)

    if opcion == "por_numero_de_series":

        w = np.array([len(series_por_dimension[d]) for d in dimensiones], dtype=float)

    elif opcion == "pca_dimension" and len(dimensiones) > 1:

        _, vectores = componentes_principales(matriz_correlaciones(subindices))

        w = vectores[:, 0] ** 2

    else:

        w = np.ones(len(dimensiones))

    return pd.DataFrame(np.tile(w / w.sum(), (len(subindices), 1)), index=subindices.index, columns=dimensiones)


def combinar(valores, pesos, forma, faltantes):
    """Combina las columnas de valores con los pesos (tabla del mismo tamano o serie) segun la forma de agregacion."""

    if isinstance(pesos, pd.Series):

        pesos = pd.DataFrame(np.tile(pesos.values, (len(valores), 1)), index=valores.index, columns=valores.columns)

    pesos = pesos[valores.columns]

    disponible = valores.notna()

    W = pesos.where(disponible, 0.0)

    suma = W.sum(axis=1)

    Wn = W.div(suma.where(suma > 0), axis=0).fillna(0.0)

    X = valores.where(disponible, 1.0)

    if forma == "geometrica":

        r = np.exp((Wn * np.log(X.clip(lower=EPSILON_POSITIVO))).sum(axis=1))

    elif forma == "armonica":

        r = 1 / (Wn / X.clip(lower=EPSILON_POSITIVO)).sum(axis=1)

    else:

        r = (Wn * X).sum(axis=1)

        if forma == "penalizada_mp":

            desvio = np.sqrt((Wn * (X.sub(r, axis=0)) ** 2).sum(axis=1))

            r = r - desvio ** 2 / r.where(r.abs() > 0)

    r = r.where(suma > 0)

    if faltantes == "exigir_completo":

        r = r.where(disponible.all(axis=1))

    return r


def agregar_indice(panel_norm, e, R=None):
    """Agrega el panel normalizado en subindices (indicador y dimension) y en el indice final."""

    columnas = list(panel_norm.columns)

    dim = {c: dimension_de(base_de(c)) for c in columnas}

    ind = {c: INDICADOR_DE_SERIE[base_de(c)] for c in columnas}

    forma, faltantes, metodo = e["agregacion"], e["faltantes_agregacion"], e["pesos"]

    dimensiones = sorted(set(dim.values()))

    por_dim = {d: [c for c in columnas if dim[c] == d] for d in dimensiones}

    if R is None and metodo in ("pca", "inverso_correlacion"):

        R = matriz_correlaciones(panel_norm)

    opcion_dimension = "por_numero_de_series" if metodo == "iguales_planos" else e["pesos_dimension"]

    jerarquico = metodo == "iguales_por_niveles"

    subindicadores, pesos_serie_dim, subindices = {}, {}, {}

    for d in dimensiones:

        series = por_dim[d]

        if jerarquico:

            indicadores = list(dict.fromkeys(ind[c] for c in series))

            for i in indicadores:

                miembros = [c for c in series if ind[c] == i]

                subindicadores[(d, i)] = combinar(panel_norm[miembros], pesos_iguales(miembros, panel_norm.index), forma, faltantes)

            tabla_ind = pd.DataFrame({i: subindicadores[(d, i)] for i in indicadores})

            subindices[d] = combinar(tabla_ind, pesos_iguales(indicadores, panel_norm.index), forma, faltantes)

            # peso efectivo de cada serie dentro de la dimension (para el orden plano)
            pesos_serie_dim[d] = pd.DataFrame(
                {c: 1 / len(indicadores) / sum(ind[x] == ind[c] for x in series) for c in series}, index=panel_norm.index
            )

        else:

            pesos_serie_dim[d] = pesos_de_series(panel_norm, series, "iguales" if metodo == "iguales_planos" else metodo, R)

            subindices[d] = combinar(panel_norm[series], pesos_serie_dim[d], forma, faltantes)

    tabla_dim = pd.DataFrame(subindices)

    pesos_dim = pesos_de_dimensiones(tabla_dim, por_dim, opcion_dimension)

    if e["orden_agregacion"] == "plana":

        efectivos = pd.concat([pesos_serie_dim[d].mul(pesos_dim[d], axis=0) for d in dimensiones], axis=1)

        indice = combinar(panel_norm, efectivos, forma, faltantes)

    else:

        efectivos = pd.concat([pesos_serie_dim[d].mul(pesos_dim[d], axis=0) for d in dimensiones], axis=1)

        indice = combinar(tabla_dim, pesos_dim, forma, faltantes)

    return {
        "indice": indice, "subindices_dimension": tabla_dim,
        "subindices_indicador": pd.DataFrame({f"{d}|{i}": s for (d, i), s in subindicadores.items()}),
        "pesos_dimension": pesos_dim, "pesos_efectivos": efectivos,
    }


def indice_con(cambio=None, panel=None):
    """Agrega el panel normalizado con el escenario base modificado por 'cambio' (un diccionario de decisiones). Devuelve el resultado completo."""

    return agregar_indice(panel_normalizado if panel is None else panel, {**ESCENARIO_BASE, **(cambio or {})})


def pesos_aplicados(panel_norm, e):
    """Peso con que cada serie entra al indice en cada trimestre, ya redistribuidos los faltantes (0 donde no hay dato).

    La media aritmetica es lineal: lo que se mueve el indice cuando una serie sube un punto es exactamente el peso que tiene en ese trimestre."""

    e_lineal = {**e, "agregacion": "aritmetica"}

    indice_inicial = agregar_indice(panel_norm, e_lineal)["indice"]

    pesos = {}

    for variable in panel_norm.columns:

        movido = panel_norm.copy()

        movido[variable] = movido[variable] + 1.0

        pesos[variable] = (agregar_indice(movido, e_lineal)["indice"] - indice_inicial).fillna(0.0)

    return pd.DataFrame(pesos).where(panel_norm.notna(), 0.0)


def peso_por_dimension(pesos):
    """Suma por dimension de una tabla de pesos (trimestres x series)."""

    return pesos.T.groupby([dim_codigo(c) for c in pesos.columns]).sum().T


