def propiedades_de_los_pesos(m):
    """Propiedades del reparto de pesos que produce el esquema m (pesos medios de los 44 trimestres)."""

    pesos = agregados_pesos[m]["pesos_efectivos"]

    medios = pesos.mean()

    por_dimension = medios.groupby([dim_codigo(c) for c in medios.index]).sum()

    por_indicador = medios.groupby([INDICADOR_DE_SERIE[base_de(c)] for c in medios.index]).sum()

    razones = por_indicador.groupby([int(i.split(".")[0]) for i in por_indicador.index]).apply(lambda x: x.max() / x.min() if x.min() > 0 else np.inf)

    return {
        "peso_minimo": medios.min(),
        "peso_maximo": medios.max(),
        "numero_efectivo_de_series": 1 / (medios ** 2).sum(),
        "series_casi_eliminadas": int((medios < FRACCION_PESO_CASI_NULO * peso_plano_7_1).sum()),
        "razon_entre_indicadores": razones.max(),
        "peso_de_la_dimension_mayor": por_dimension.max(),
        "peso_de_la_dimension_menor": por_dimension.min(),
        "peso_del_tono": medios[serie_tono].sum(),
        "cambio_con_la_muestra": 0.5 * (medios - agregados_pesos_recortado[m]["pesos_efectivos"].mean()).abs().sum(),
        "cambio_trimestral": 0.5 * pesos.diff().abs().sum(axis=1).mean(),
    }


