def brecha_de_tension(subindice_dim4):
    """Promedio de la dimension 4 en los trimestres de volumen alto y tono desfavorable menos el del resto."""

    return subindice_dim4[trimestres_tension_7].mean() - subindice_dim4[~trimestres_tension_7].mean()


filas = []

