fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 4.2))

pesos_dimensiones_7 = pd.DataFrame({o: tabla_pesos_dimension.loc[o, [f"peso_dim_{d}" for d in subindices_7_2.columns]].values for o in OPCIONES_PESOS_DIMENSION}, index=[str(d) for d in subindices_7_2.columns])

pesos_dimensiones_7.plot(kind="bar", rot=0, ax=ax1, width=0.8)

ax1.set_title("7.2.a Peso de cada dimension segun la opcion", fontsize=9)

