for opcion in OPCIONES_ESTACIONALIDAD:

    ax2.plot(range(len(trimestres_panel)), ajustar_estacionalidad(indice_base_8_3, opcion).values, label=opcion, lw=2.6 if opcion == ESCENARIO_BASE["estacionalidad"] else 1.0, color="k" if opcion == ESCENARIO_BASE["estacionalidad"] else None)

