ax2.plot(range(len(trimestres_8_4)), indice_por_base_8[f"indice_{BASE_DE_PRESENTACION_POR_DEFECTO}"].values, color="k", lw=2.2, label="indice general")

ax2.axhline(MEDIA_ESCALA, color="k", lw=0.8, ls=":")

