lectura(
    f"el indice general es el promedio de las {subindices_grafico.shape[1]} dimensiones (diferencia maxima {float((promedio_dimensiones - indice_base).abs().max()):.1e} puntos); "
    f"va de {indice_base.min():.1f} ({indice_base.idxmin()}) a {indice_base.max():.1f} ({indice_base.idxmax()}) con media {indice_base.mean():.1f}, "
    f"y las dimensiones se separan hasta {float((subindices_grafico.max(axis=1) - subindices_grafico.min(axis=1)).max()):.1f} puntos entre ellas."
)


# 2. Medidas de comparacion

def estandarizar(s):
    """Serie con media cero y desvio uno (para comparar indices de escalas distintas)."""

    return (s - s.mean()) / s.std(ddof=1) if s.std(ddof=1) > 0 else s * np.nan


def comparar_con_base(indice, base):
    """Medidas de cercania entre un indice y el base, sobre los trimestres que ambos tienen."""

    c = pd.concat([indice, base], axis=1, keys=["a", "b"]).dropna()

    if len(c) < 8:

        return {"trimestres_comunes": len(c)}

    return {
        "trimestres_comunes": len(c),
        "spearman_niveles": float(stats.spearmanr(c["a"], c["b"]).statistic),
        "spearman_cambios": float(stats.spearmanr(c["a"].diff().dropna(), c["b"].diff().dropna()).statistic),
        "rmse_estandarizado": float(np.sqrt(((estandarizar(c["a"]) - estandarizar(c["b"])) ** 2).mean())),
        "max_desplazamiento": int((c["a"].rank() - c["b"].rank()).abs().max()),
    }


# escala de lectura del RMSE estandarizado (convencion de lectura, no una prueba estadistica)
MOVIMIENTO_POCO = 0.15  # parametro de esta subseccion: por debajo de este RMSE el indice casi no cambia de forma

MOVIMIENTO_MUCHO = 0.50  # parametro de esta subseccion: por encima de este RMSE el indice cambia de forma de manera apreciable


def leer_movimiento(rmse):
    """Etiqueta de lectura de un RMSE estandarizado segun MOVIMIENTO_POCO y MOVIMIENTO_MUCHO."""

    if pd.isna(rmse):

        return "sin dato"

    return "poco" if rmse < MOVIMIENTO_POCO else "mucho" if rmse > MOVIMIENTO_MUCHO else "moderado"


def correlacion_equivalente(rmse, n):
    """Correlacion de Pearson que corresponde a un RMSE entre dos series estandarizadas de n trimestres: 1 - rmse^2 * n / (2 * (n - 1))."""

    return 1 - rmse ** 2 * n / (2 * (n - 1))


def perturbaciones_de(indice, semilla=SEMILLA):
    """Indices alterados de una manera conocida, para comprobar que detecta cada medida."""

    g = np.random.default_rng(semilla)

    n = len(indice)

    sd = float(indice.std())

    return {
        "suma 5 puntos a todos los trimestres": indice + 5,
        "cambia la escala (desvio doble alrededor de 100)": MEDIA_ESCALA + 2 * (indice - MEDIA_ESCALA),
        "ruido de 10% del desvio del indice": indice + g.normal(0, 0.1 * sd, n),
        "ruido de 50% del desvio del indice": indice + g.normal(0, 0.5 * sd, n),
        "tendencia agregada (0,2 puntos por trimestre)": indice + 0.2 * np.arange(n),
        "indice desplazado un trimestre": indice.shift(1),
        "el ultimo trimestre cambia 15 puntos": indice.where(indice.index != indice.index[-1], indice + 15),
        "orden temporal invertido": pd.Series(indice.values[::-1], index=indice.index),
        "serie sin relacion (ruido alrededor de 100)": pd.Series(MEDIA_ESCALA + g.normal(0, sd, n), index=indice.index),
    }


perturbaciones = perturbaciones_de(indice_base)

filas_calibracion = []

for nombre, serie in perturbaciones.items():

    medidas = comparar_con_base(serie, indice_base)

    filas_calibracion.append(
        {
            "perturbacion": nombre, **medidas,
            "dif_media_en_puntos": float((serie - indice_base).abs().mean()),
            "lectura": leer_movimiento(medidas.get("rmse_estandarizado", np.nan)),
        }
    )

tabla_calibracion_medidas = pd.DataFrame(filas_calibracion).set_index("perturbacion")

print("Tabla 9.0.c. Que detecta cada medida: indices alterados de una manera conocida contra el indice base")
print(tabla_calibracion_medidas.round(3).to_string())

# TABLA 9.0.c - QUE MUESTRA
#   El indice base comparado con versiones alteradas de una forma conocida, con las cuatro medidas de comparacion y la
#   diferencia en puntos.
# TABLA 9.0.c - QUE SE ENCONTRO
#   - Sumar 5 puntos o duplicar la escala deja todas las medidas de forma intactas (RMSE 0,00), pero la diferencia en
#     puntos llega a 5,0.
#   - El ruido de 10% da RMSE 0,08 (poco) y el de 50%, 0,44 (moderado).
#   - Cambiar solo el ultimo trimestre 15 puntos da RMSE 0,54 (mucho) aunque el orden de niveles no cambia (1,00).
#   - Desplazar el indice un trimestre, invertirlo o reemplazarlo por ruido da RMSE de 0,97 a 1,51.
# TABLA 9.0.c - QUE IMPLICA
#   Las medidas de forma distinguen lo que deben y no se dejan enganar por la escala. La diferencia en puntos si.
forma_igual = tabla_calibracion_medidas.loc[["suma 5 puntos a todos los trimestres", "cambia la escala (desvio doble alrededor de 100)"]]

un_trimestre = tabla_calibracion_medidas.loc["el ultimo trimestre cambia 15 puntos"]

ruido_chico, ruido_grande = tabla_calibracion_medidas.loc["ruido de 10% del desvio del indice"], tabla_calibracion_medidas.loc["ruido de 50% del desvio del indice"]

sin_relacion = tabla_calibracion_medidas.loc["serie sin relacion (ruido alrededor de 100)"]

lectura(
    f"sumar una constante o cambiar la escala deja el rmse en {forma_igual['rmse_estandarizado'].max():.3f} y el desplazamiento en {int(forma_igual['max_desplazamiento'].max())}, "
    f"pero la diferencia en puntos llega a {forma_igual['dif_media_en_puntos'].max():.1f}; el ruido de 10% da spearman de cambios {ruido_chico['spearman_cambios']:.2f} y el de 50% {ruido_grande['spearman_cambios']:.2f} "
    f"(rmse {ruido_chico['rmse_estandarizado']:.2f} y {ruido_grande['rmse_estandarizado']:.2f}); cambiar un solo trimestre mueve su posicion {int(un_trimestre['max_desplazamiento'])} lugares con spearman de niveles {un_trimestre['spearman_niveles']:.3f}; "
    f"la serie sin relacion da spearman {sin_relacion['spearman_niveles']:.2f} y rmse {sin_relacion['rmse_estandarizado']:.2f}."
)


# tabla 2: a que correlacion equivale cada nivel del RMSE (justifica la escala poco / moderado / mucho)
n_comparacion = int(indice_base.notna().sum())

tabla_escala_lectura = pd.DataFrame({"rmse_estandarizado": [0.05, 0.10, MOVIMIENTO_POCO, 0.30, MOVIMIENTO_MUCHO, 0.75, 1.00, 1.41]})

