tabla_escala_lectura["variacion_compartida"] = tabla_escala_lectura["pearson_equivalente"].clip(lower=0) ** 2

tabla_escala_lectura["lectura"] = tabla_escala_lectura["rmse_estandarizado"].apply(leer_movimiento)

print(f"\nTabla 9.0.d. Escala de lectura del RMSE estandarizado ({n_comparacion} trimestres)")
