# 2. Ediciones nuevas: que se congela y cuanto se revisa lo publicado

def congelar_criterios(resultado):
    """Criterios de una edicion publicada: series, lista de logaritmos y valores de referencia de cada serie."""

    e = resultado["escenario"]

    panel_t = resultado["panel_transformado"]

    filas_ref = filas_del_periodo(e["periodo_referencia"], list(panel_t.index))

    return {
        "series": list(resultado["series"]),
        "con_log": list(resultado["info_transformacion"]["con_transformacion"]),
        "referencia": {v: valores_referencia(v, panel_t, filas_ref) for v in resultado["series"]},
        "periodo": e["periodo_referencia"],
    }


NOMBRE_POLITICA_CONGELADA = "congelada (series, logaritmos y escala)"


def politicas_de_actualizacion(corte, congelados):
    """Las cuatro politicas que se comparan para publicar la edicion completa, como cambio sobre el escenario base."""

    return {
        NOMBRE_POLITICA_CONGELADA: {"congelados": congelados},
        "periodo fijo, criterios recalculados": {"periodo_referencia": f"2015-{corte[:4]}"},
        "periodo base redefinido (decada completa)": {},
        "referencia movil (ventana completa)": {"periodo_referencia": "ventana_completa"},
    }


def probar_revisiones(ediciones=None, con_detalle=False):
    """Cuanto se revisa el indice ya publicado al agregar datos, segun la politica de actualizacion.

    Con con_detalle=True devuelve ademas los indices de cada edicion, de cada politica y los criterios congelados."""

    filas, publicadas, nuevas, criterios = [], {}, {}, {}

    for corte in (ediciones or EDICIONES_PASADAS):

        ventana_corte = f"2015-{corte}"

        OPCIONES_VENTANA.setdefault(ventana_corte, ("2015-Q1", corte))

        publicada = construir_indice({"ventana": ventana_corte})

        congelados = congelar_criterios(publicada)

        publicadas[corte], criterios[corte] = publicada["indice"], congelados

        for nombre, cambio in politicas_de_actualizacion(corte, congelados).items():

            try:

                nueva = construir_indice(cambio)["indice"]

                nuevas[(corte, nombre)] = nueva

                comunes = publicada["indice"].dropna().index.intersection(nueva.dropna().index)

                revision = (nueva.loc[comunes] - publicada["indice"].loc[comunes]).abs()

                filas.append(
                    {
                        "edicion_publicada": corte, "politica": nombre, "trimestres_revisados": len(comunes),
                        "revision_media_puntos": revision.mean(), "revision_maxima_puntos": revision.max(),
                    }
                )

            except Exception as error:

                filas.append({"edicion_publicada": corte, "politica": nombre, "error": f"{type(error).__name__}: {str(error)[:60]}"})

    tabla = pd.DataFrame(filas)

    return (tabla, {"publicadas": publicadas, "nuevas": nuevas, "congelados": criterios}) if con_detalle else tabla


tabla_revisiones, detalle_revisiones = probar_revisiones(con_detalle=True)

print("Tabla 9.2.e. Revision de lo ya publicado segun la politica de actualizacion")
print(tabla_revisiones.round(3).to_string(index=False))

# TABLA 9.2.e - QUE MUESTRA
